(()=>{'use strict';const key='buchee_aurora_intro_seen_v1';const slides=[{image:'https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=1100&q=82',title:'Birlikte daha fazlası.',text:'Yeni insanlarla tanış. Paylaşmak istediğin her şey için kendine ait bir alan bul.',eyebrow:'01 / TOPLULUK'},{image:'https://images.unsplash.com/photo-1490730141103-6cac27aaab94?auto=format&fit=crop&w=1100&q=82',title:'Keşfetmeye değer.',text:'Yeni fikirleri, hikâyeleri ve ilgi duyduğun içerikleri tek bir yerde keşfet.',eyebrow:'02 / KEŞFET'},{image:'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1100&q=82',title:'Senin alanın. Senin sesin.',text:'Kendi hikâyeni paylaş ve sana ilham veren topluluğa katıl.',eyebrow:'03 / PAYLAŞ'}];let step=0,shown=false;const root=document.createElement('section');root.id='buchee-aurora-intro';root.hidden=true;root.setAttribute('aria-label','Buchee tanıtımı');root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');function render(){const x=slides[step];root.innerHTML='<div class="buchee-aurora-panel"><div class="buchee-aurora-photo" style="background-image:linear-gradient(180deg,transparent 15%,rgba(0,0,0,.72) 100%),url(&quot;'+x.image+'&quot;)"></div><div class="buchee-aurora-top"><div class="buchee-aurora-brand">Buchee<span class="buchee-brand-dot">.</span></div><button type="button" class="buchee-aurora-skip" data-intro="skip">Atla</button></div><div class="buchee-aurora-bottom"><span class="buchee-aurora-eyebrow">'+x.eyebrow+'</span><h1>'+x.title+'</h1><p>'+x.text+'</p><div class="buchee-aurora-dots">'+slides.map((_,i)=>'<i class="'+(i===step?'active':'')+'"></i>').join('')+'</div><button type="button" class="buchee-aurora-primary" data-intro="next">'+(step===slides.length-1?'Kayıt ol':'Devam et')+' <span aria-hidden="true">→</span></button><button type="button" class="buchee-aurora-secondary" data-intro="login">Zaten hesabın var mı? Giriş yap</button></div></div>'}function close(mode){root.hidden=true;document.body.style.removeProperty('overflow');try{localStorage.setItem(key,'1')}catch{}if(mode){const b=document.querySelector('#auth-root [data-auth="'+mode+'"]');if(b)b.click()}}root.addEventListener('click',e=>{const a=e.target.closest('[data-intro]');if(!a)return;const v=a.dataset.intro;if(v==='next'&&step<slides.length-1){step++;render()}else close(v==='login'?'login':v==='next'?'signup':null)});function check(){if(shown||!root.hidden)return;const auth=document.getElementById('auth-root'),app=document.getElementById('app-root');if(!auth||!app||auth.classList.contains('hidden')||!app.classList.contains('hidden')||!auth.querySelector('#auth-form'))return;let seen=false;try{seen=localStorage.getItem(key)==='1'}catch{}if(seen)return;shown=true;step=0;render();root.hidden=false;document.body.style.overflow='hidden'}function init(){document.body.append(root);const auth=document.getElementById('auth-root');if(auth){new MutationObserver(()=>{if(!root.hidden&&auth.classList.contains('hidden'))close();else check()}).observe(auth,{attributes:true,attributeFilter:['class'],childList:true,subtree:false})}check();setTimeout(check,600);setTimeout(check,1800)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init()})();